import * as THREE from './three.module.js';

export function batchScenery(scene){
 // Colliders retain their original world matrices for accurate raycasts.
 scene.updateMatrixWorld(true);const groups=new Map();
 for(const mesh of [...scene.children]){if(!mesh.isMesh||mesh.geometry.type!=='BoxGeometry'||Array.isArray(mesh.material)||mesh.material.transparent)continue;const key=mesh.material.uuid+mesh.castShadow+mesh.receiveShadow;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(mesh)}
 let saved=0;
 for(const meshes of groups.values()){if(meshes.length<3)continue;const first=meshes[0],batch=new THREE.InstancedMesh(new THREE.BoxGeometry(1,1,1),first.material,meshes.length);batch.castShadow=first.castShadow;batch.receiveShadow=first.receiveShadow;const transform=new THREE.Matrix4(),scale=new THREE.Matrix4();meshes.forEach((mesh,i)=>{const p=mesh.geometry.parameters;scale.makeScale(p.width,p.height,p.depth);transform.multiplyMatrices(mesh.matrixWorld,scale);batch.setMatrixAt(i,transform);scene.remove(mesh)});batch.computeBoundingSphere();batch.instanceMatrix.needsUpdate=true;scene.add(batch);saved+=meshes.length-1}
 return saved;
}

export function createAtmosphere(scene){
 const sky=new THREE.Mesh(new THREE.SphereGeometry(430,32,16),new THREE.ShaderMaterial({side:THREE.BackSide,depthWrite:false,uniforms:{time:{value:0},sunDirection:{value:new THREE.Vector3(-60,32,-55).normalize()}},vertexShader:`varying vec3 direction;void main(){direction=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,fragmentShader:`varying vec3 direction;uniform float time;uniform vec3 sunDirection;float noise(vec3 p){return fract(sin(dot(floor(p),vec3(127.1,311.7,74.7)))*43758.5453);}float smoothNoise(vec3 p){vec3 f=fract(p);f=f*f*(3.-2.*f);vec3 i=floor(p);return mix(mix(mix(noise(i),noise(i+vec3(1,0,0)),f.x),mix(noise(i+vec3(0,1,0)),noise(i+vec3(1,1,0)),f.x),f.y),mix(mix(noise(i+vec3(0,0,1)),noise(i+vec3(1,0,1)),f.x),mix(noise(i+vec3(0,1,1)),noise(i+vec3(1,1,1)),f.x),f.y),f.z);}void main(){vec3 d=normalize(direction);float h=max(d.y,0.);vec3 color=mix(vec3(.71,.64,.48),vec3(.16,.29,.38),pow(h,.45));float cloud=smoothNoise(d*12.+vec3(time*.005,0.,0.))*.65+smoothNoise(d*30.)*.25;float band=smoothstep(.12,.3,h)*(1.-smoothstep(.75,.95,h));color=mix(color,vec3(.76,.73,.63),smoothstep(.42,.62,cloud)*band*.72);float sun=max(dot(d,sunDirection),0.);color+=vec3(1.,.68,.28)*pow(sun,55.)*.38;color+=vec3(1.,.9,.68)*pow(sun,1500.);gl_FragColor=vec4(color,1.);}` }));scene.add(sky);
 const count=160,positions=new Float32Array(count*3);for(let i=0;i<count;i++){positions[i*3]=Math.sin(i*47.13)*58;positions[i*3+1]=1+(i%17)*.6;positions[i*3+2]=Math.cos(i*13.79)*70}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));const dust=new THREE.Points(geometry,new THREE.PointsMaterial({color:'#ffe2a8',size:.055,transparent:true,opacity:.3,depthWrite:false}));scene.add(dust);
 const cloth=new THREE.Mesh(new THREE.PlaneGeometry(6,2,16,4),new THREE.MeshStandardMaterial({color:'#647153',roughness:1,side:THREE.DoubleSide,transparent:true,opacity:.7}));cloth.position.set(34,4.2,29);scene.add(cloth);const original=cloth.geometry.attributes.position.array.slice();
 return {update(time,reduced){sky.material.uniforms.time.value=time;dust.rotation.y=time*.005;if(reduced)return;const p=cloth.geometry.attributes.position;for(let i=0;i<p.count;i++)p.setZ(i,original[i*3+2]+Math.sin(time*2.3+original[i*3]*1.2)*.16*(original[i*3]+3)/6);p.needsUpdate=true;cloth.geometry.computeVertexNormals()}};
}

export function createAudio(){
 let context,master,windGain,muted=false,noiseBuffer;function unlock(){if(!context){context=new(window.AudioContext||window.webkitAudioContext)();master=context.createGain();master.gain.value=muted?0:.65;master.connect(context.destination);noiseBuffer=context.createBuffer(1,context.sampleRate*2,context.sampleRate);const data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const source=context.createBufferSource();source.buffer=noiseBuffer;source.loop=true;const filter=context.createBiquadFilter();filter.type='lowpass';filter.frequency.value=230;windGain=context.createGain();windGain.gain.value=.045;source.connect(filter);filter.connect(windGain);windGain.connect(master);source.start()}context.resume()}
 function noise(duration,volume,frequency=1500,delay=0){if(!context)return;const t=context.currentTime+delay,source=context.createBufferSource(),filter=context.createBiquadFilter(),gain=context.createGain();source.buffer=noiseBuffer;filter.type='lowpass';filter.frequency.value=frequency;gain.gain.setValueAtTime(volume,t);gain.gain.exponentialRampToValueAtTime(.001,t+duration);source.connect(filter);filter.connect(gain);gain.connect(master);source.start(t);source.stop(t+duration)}
 function tone(frequency,duration,volume,delay=0){if(!context)return;const t=context.currentTime+delay,o=context.createOscillator(),g=context.createGain();o.type='sine';o.frequency.setValueAtTime(frequency,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,frequency*.35),t+duration);g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(master);o.start(t);o.stop(t+duration)}
 return {unlock,shot(indoor){noise(.065,.45,4200);noise(.15,.14,850);tone(95,.12,.3);noise(.17,indoor?.09:.035,1200,.1);noise(.12,.025,600,.24)},hit(){tone(750,.045,.045);tone(1050,.055,.025,.04)},step(sprint){noise(.07,sprint?.075:.04,650);tone(90,.05,.03)},land(power){noise(.12,.06+power*.05,800);tone(65,.14,.06)},reload(){noise(.055,.08,3000);noise(.07,.1,2800,.8);tone(160,.05,.05,1.15)},finish(){tone(620,.17,.08);tone(820,.2,.08,.15)},update(indoor,active){if(windGain)windGain.gain.setTargetAtTime(active?(indoor?.015:.045):.008,context.currentTime,.4)},setMuted(value){muted=value;if(master)master.gain.setTargetAtTime(value?0:.65,context.currentTime,.08)},isMuted:()=>muted};
}

export function createInterface({targets,solids,onStartDrill,onContinue}){
 const map=document.querySelector('#minimap'),ctx=map.getContext('2d'),challenge=document.querySelector('#challenge'),summary=document.querySelector('#drill-summary'),objective=document.querySelector('#objective'),bearing=document.querySelector('#bearing');let running=false,time=90,seen=new Set(),score=0,shots=0,hits=0,totalShots=0,totalHits=0,finished=false;const blocks=solids.filter(b=>b.minY>=-.1&&b.maxY>2.5&&b.maxX-b.minX>3&&b.maxZ-b.minZ>1);
 function begin(){running=true;finished=false;time=90;seen.clear();for(const t of targets)t.board.material.color.setHex(0xffffff);score=0;shots=0;hits=0;summary.hidden=true;onStartDrill?.();challenge.textContent='RANGE DRILL · 90s';objective.textContent='Hit all 8 targets before time runs out';document.querySelector('#range-progress').style.width='0%'}
 function end(success){running=false;finished=true;challenge.textContent=success?'DRILL COMPLETE':'TIME EXPIRED';summary.hidden=false;document.querySelector('#drill-title').textContent=success?'Range cleared.':'Run it again.';document.querySelector('#drill-result').textContent=`${seen.size} / 8 targets · ${score} points · ${shots?Math.round(hits/shots*100):0}% accuracy`;audioEvent(success)}let audioEvent=()=>{};
 document.querySelector('#restart-drill').onclick=begin;document.querySelector('#dismiss-drill').onclick=()=>{summary.hidden=true;finished=false;onContinue?.()};document.querySelector('#drill-start').onclick=begin;
 function hit(target,quality){totalHits++;if(!running)return;hits++;score+=quality;if(!seen.has(target)){seen.add(target);targets[target].board.material.color.setHex(0x9bc6aa);document.querySelector('#range-progress').style.width=`${seen.size/targets.length*100}%`;if(seen.size===targets.length)end(true)}}
 function shot(){totalShots++;if(running)shots++}
 function update(dt,pos,yaw,active){if(running&&active){time=Math.max(0,time-dt);challenge.textContent=`RANGE DRILL · ${Math.ceil(time)}s`;objective.textContent=`${seen.size} / ${targets.length} targets · ${score} points`;if(time===0)end(false)}if(!running&&!finished){challenge.textContent='FREE ROAM';objective.textContent='Explore the rooftops · Practice on marked targets'}document.querySelector('#accuracy').textContent=totalShots?`${Math.round(totalHits/totalShots*100)}% ACCURACY`:'RANGE READY';let degrees=((-yaw*180/Math.PI)%360+360)%360;const dirs=['N','NE','E','SE','S','SW','W','NW'];bearing.textContent=`${dirs[Math.round(degrees/45)%8]}  ${String(Math.round(degrees)).padStart(3,'0')}°`;ctx.clearRect(0,0,180,180);ctx.fillStyle='#132127';ctx.fillRect(0,0,180,180);const sx=x=>90+x*.95,sz=z=>90+z*.95;ctx.fillStyle='#63716a';ctx.fillRect(sx(-60),sz(-74),114,140.6);ctx.fillStyle='#899389';ctx.fillRect(sx(-48),sz(-71),91.2,26.6);ctx.fillRect(sx(-48),sz(43),91.2,26.6);ctx.fillStyle='#263b3a';for(const b of blocks)ctx.fillRect(sx(b.minX),sz(b.minZ),(b.maxX-b.minX)*.95,(b.maxZ-b.minZ)*.95);ctx.strokeStyle='#bfb691';ctx.lineWidth=1;ctx.strokeRect(sx(-68),sz(-42),7.6,79.8);ctx.strokeRect(sx(60),sz(-42),7.6,79.8);ctx.fillStyle='#ffffffaa';ctx.font='9px Arial';ctx.textAlign='center';ctx.fillText('NORTH',90,35);ctx.fillText('SOUTH',90,151);for(let i=0;i<targets.length;i++){const t=targets[i];ctx.fillStyle=seen.has(i)?'#7ac9b6':'#efbf74';ctx.beginPath();ctx.arc(sx(t.group.position.x),sz(t.group.position.z),2.5,0,Math.PI*2);ctx.fill()}ctx.save();ctx.translate(sx(pos.x),sz(pos.z));ctx.rotate(-yaw);ctx.fillStyle='#f7f8ed';ctx.beginPath();ctx.moveTo(0,-5);ctx.lineTo(-3.5,4);ctx.lineTo(3.5,4);ctx.closePath();ctx.fill();ctx.restore()}
 return {begin,update,hit,shot,onFinish(fn){audioEvent=fn},isRunning:()=>running,stats:()=>({running,time,score,targets:seen.size,shots,hits})};
}
